<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php';require_once BASE_PATH.'/shared/delivery/ReleaseFlags.php';
if(!defined('DELIVERY_ENABLED')||DELIVERY_ENABLED!==true){http_response_code(503);exit('Delivery is not enabled.');}
$partnerView=defined('DELIVERY_PARTNER_ACCOUNTING')&&DELIVERY_PARTNER_ACCOUNTING===true;
if($partnerView){
    try{$actor=$partnerAuth->actor($_SESSION['partner']);if(!\Hambelela\Delivery\PartnerAccess::can($actor,'shared_reporting')||!\Hambelela\Delivery\PartnerAccess::can($actor,'accounting'))throw new DomainException();}catch(Throwable $e){http_response_code(403);exit('Shared Accounting access denied.');}
    $expense=false;$rates=false;
    require_once BASE_PATH.'/shared/delivery/PartnerShell.php';\Hambelela\Delivery\PartnerShell::begin($actor);
}else{
require_once BASE_PATH.'/apps/operations/operations.php';require_login();
require_once BASE_PATH.'/shared/delivery/FrontSession.php';
try{$actor=\Hambelela\Delivery\FrontSession::actor(db(),(int)(current_user()['id']??0));if(!\Hambelela\Delivery\DeliveryPolicy::can($actor,'delivery_accounting_view'))throw new DomainException();}catch(DomainException $e){http_response_code(403);exit('Accounting access denied.');}
header('Cache-Control: no-store');
$expense=\Hambelela\Delivery\DeliveryPolicy::can($actor,'delivery_accounting_expenses_manage');$rates=\Hambelela\Delivery\DeliveryPolicy::can($actor,'delivery_rates_manage');
require_once BASE_PATH.'/shared/delivery/PortalShell.php';
\Hambelela\Delivery\PortalShell::begin(true);

}

?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Delivery accounting · Hambelela</title></head><body data-delivery-accounting="true" data-accounting-api="<?=$partnerView?'admin-api.php':'accounting-api.php'?>"><main class="delivery-main"><header class="pagehead"><div><div class="eyebrow">DELIVERY · ACCOUNTING</div><h1>Delivery fund</h1><p>Delivery income only. Product collections and partner COD are held separately.</p></div><a class="secondary" href="workspace.php">Delivery board</a></header><p id="message" role="status"></p><form id="range" class="toolbar"><label>From<input name="from" type="date" required value="<?=date('Y-m-01')?>"></label><label>To<input name="to" type="date" required value="<?=date('Y-m-d')?>"></label><button class="primary">Apply dates</button><button type="button" class="secondary" id="export">Export CSV</button></form><section id="summary" class="kpis" aria-label="Financial summary"></section><div class="tabs accounting-tabs" role="tablist" aria-label="Accounting views"><button class="secondary is-active" role="tab" aria-selected="true" aria-controls="deliveries" data-tab="deliveries">Deliveries</button><button class="secondary" role="tab" aria-selected="false" aria-controls="expenses" data-tab="expenses">Expenses</button></div><section id="deliveries" class="panel"><h2>Delivery history</h2><p>Up to 500 records in the selected period. Narrow the dates for larger reports.</p><div class="tablewrap" id="delivery-table"></div></section><section id="expenses" class="panel" hidden><div class="sectionhead"><h2>Expenses</h2><?php if($expense):?><button class="primary" id="add-expense">Add expense</button><?php endif;?></div><div class="tablewrap" id="expense-table"></div></section><?php if($rates):?><section id="pricing" class="panel" hidden><div class="sectionhead"><h2>Delivery areas and rates</h2><button class="primary" id="add-zone">Add area</button></div><p>Rate changes apply to new deliveries. Existing agreed fees are preserved.</p><div class="tablewrap" id="zone-table"></div></section><?php endif;?><dialog id="expense-dialog"><form id="expense-form"><h2>Record expense</h2><input type="hidden" name="replace_id"><label>Date<input type="date" name="date" required></label><label>Category<select name="category"><option>Fuel</option><option>Airtime / Data</option><option>Bike Maintenance</option><option>Repair</option><option>Parking</option><option>Other</option></select></label><label>Amount (N$)<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Supplier<input name="supplier" maxlength="190"></label><label>Description<textarea name="description" maxlength="2000" required></textarea></label><label class="check"><input type="checkbox" name="paid">Payment has actually been made</label><label>Correction reason (required when replacing)<input name="reason" maxlength="500"></label><p class="form-error" role="alert"></p><div class="modalactions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save expense</button></div></form></dialog><dialog id="zone-dialog"><form id="zone-form"><h2>Delivery rate</h2><input name="id" type="hidden"><input name="version" type="hidden"><label>Area<input name="area" maxlength="190" required></label><label>Aliases, separated by commas<input name="aliases" maxlength="1000"></label><label>Fee (N$)<input name="fee" type="number" min="0" step="0.01" required></label><label class="check"><input name="active" type="checkbox" checked>Available for new deliveries</label><p class="form-error" role="alert"></p><div class="modalactions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save rate</button></div></form></dialog></main><script src="<?=htmlspecialchars(BASE_URL,ENT_QUOTES)?>/assets/js/delivery-accounting.js?v=<?=filemtime(BASE_PATH.'/assets/js/delivery-accounting.js')?>"></script><script defer src="<?=htmlspecialchars(BASE_URL,ENT_QUOTES)?>/assets/js/delivery-areas.js?v=<?=filemtime(BASE_PATH.'/assets/js/delivery-areas.js')?>"></script></body></html>
